// Two bounded contexts — same concept, different models

// Billing context
struct BillingCustomer {
    let customerId: CustomerID
    var billingAddress: Address
    var paymentMethods: [PaymentMethod]
    var invoiceHistory: [Invoice]
}

// Support context
struct SupportCustomer {
    let customerId: CustomerID
    var tickets: [SupportTicket]
    var sentimentScore: Double
    var preferredChannel: ContactChannel
}

// Cross-context reference: only the shared ID leaks across
struct SupportTicket {
    let ticketId: TicketID
    let customerId: CustomerID   // ID only — no BillingCustomer reference
    var subject: String
}

// Ubiquitous language applied: domain expert says "lapse", code says "lapse"
struct InsurancePolicy {
    let policyNumber: PolicyNumber
    private(set) var status: PolicyStatus
    private(set) var premiumDueDate: Date

    // Method name matches domain vocabulary exactly
    mutating func lapse(on date: Date) throws {
        guard status == .active else {
            throw PolicyError.cannotLapseFromStatus(status)
        }
        guard date >= premiumDueDate else {
            throw PolicyError.premiumNotYetOverdue
        }
        status = .lapsed
    }
}

// Order aggregate — root enforces the cross-line invariant
struct Order {
    let orderId: OrderID
    let customerId: CustomerID   // cross-aggregate: ID only
    private(set) var lines: [OrderLine]
    private let maxLineCount: Int = 50

    mutating func addLine(_ line: OrderLine) throws {
        guard lines.count < maxLineCount else {
            throw OrderError.lineCountExceeded
        }
        lines.append(line)
    }

    func confirm() throws -> OrderConfirmed {
        guard !lines.isEmpty else {
            throw OrderError.noLines
        }
        return OrderConfirmed(orderId: orderId)
    }
}

// OrderLine is an interior entity — no external repository
struct OrderLine {
    let lineId: LineID
    let productId: ProductID    // cross-aggregate: ID only
    let quantity: Quantity
    let unitPrice: Money
}

// Value object: equality by attributes, immutable, no database ID
struct Money: Equatable, Hashable {
    let amount: Decimal
    let currency: Currency

    // Side-effect-free behavior — returns new instance
    func adding(_ other: Money) throws -> Money {
        guard currency == other.currency else {
            throw MoneyError.currencyMismatch(currency, other.currency)
        }
        return Money(amount: amount + other.amount, currency: currency)
    }

    func applying(discount: Percentage) -> Money {
        Money(amount: amount * (1 - discount.fraction), currency: currency)
    }
}

// Usage — no mutation; new values produced
let price = Money(amount: 99.99, currency: .usd)
let discounted = price.applying(discount: Percentage(10))

// Repository interface — lives in the domain layer
protocol OrderRepository {
    func findById(_ id: OrderID) async throws -> Order?
    func findActiveFor(customerId: CustomerID) async throws -> [Order]
    func save(_ order: Order) async throws
    func nextId() -> OrderID
}

// In-memory test double — swapped at test time
final class InMemoryOrderRepository: OrderRepository {
    private var store: [OrderID: Order] = [:]

    func findById(_ id: OrderID) async throws -> Order? { store[id] }
    func findActiveFor(customerId: CustomerID) async throws -> [Order] {
        store.values.filter { $0.customerId == customerId && $0.isActive }
    }
    func save(_ order: Order) async throws { store[order.orderId] = order }
    func nextId() -> OrderID { OrderID(UUID()) }
}

// Domain service: stateless, speaks the domain language,
// coordinates between aggregates without belonging to either
struct FundsTransferService {
    func transfer(
        amount: Money,
        from source: inout Account,
        to target: inout Account
    ) throws {
        // Domain logic — no persistence, no HTTP, no queues
        guard source.availableBalance >= amount else {
            throw TransferError.insufficientFunds
        }
        guard target.canAcceptTransfer(of: amount) else {
            throw TransferError.targetAccountRestricted
        }
        try source.debit(amount)
        try target.credit(amount)
    }
}

// Application service — orchestration only, no business logic
final class PlaceOrderApplicationService {
    private let cartRepository: CartRepository
    private let orderRepository: OrderRepository
    private let eventPublisher: DomainEventPublisher

    func placeOrder(command: PlaceOrderCommand) async throws -> OrderID {
        // Load
        guard var cart = try await cartRepository.findById(command.cartId) else {
            throw OrderError.cartNotFound
        }
        // Delegate business logic entirely to the domain
        let (order, events) = try cart.checkout()
        // Save and publish
        try await orderRepository.save(order)
        for event in events { await eventPublisher.publish(event) }
        return order.orderId
    }
}

// Generic subdomain (email) hidden behind a domain-owned interface
protocol NotificationPort {
    func sendWelcome(to recipient: EmailAddress, name: PersonName) async throws
    func sendOrderConfirmation(_ order: Order) async throws
}

// Infrastructure adapter — the vendor is a detail, not part of the domain
final class SendGridNotificationAdapter: NotificationPort {
    private let client: SendGridClient

    func sendWelcome(to recipient: EmailAddress, name: PersonName) async throws {
        // Vendor-specific translation lives here, out of the domain
        let message = SendGridMessage(
            to: recipient.rawValue,
            templateId: "d-welcome-v3",
            dynamicData: ["name": name.displayName]
        )
        try await client.send(message)
    }
}

// Factory: makes complex aggregate creation explicit and domain-named
struct PolicyFactory {
    func issue(
        application: PolicyApplication,
        riskAssessment: RiskAssessment,
        effectiveDate: Date
    ) throws -> InsurancePolicy {
        // Domain creation rules live here, not in the constructor
        guard riskAssessment.score <= RiskThreshold.standard else {
            throw PolicyError.riskScoreExceedsLimit
        }
        guard effectiveDate >= Date.today else {
            throw PolicyError.effectiveDateMustBeFuture
        }
        let premium = PremiumCalculator.calculate(
            for: application.coverage,
            risk: riskAssessment
        )
        return InsurancePolicy(
            id: PolicyID(UUID()),
            holder: application.holder,
            coverage: application.coverage,
            premium: premium,
            status: .active
        )
    }
}

// Specification: encapsulates one business rule as a testable object
protocol Specification<T> {
    func isSatisfiedBy(_ candidate: T) -> Bool
}

struct PremiumEligibleSpec: Specification {
    let minimumSpend: Money
    func isSatisfiedBy(_ customer: Customer) -> Bool {
        customer.lifetimeSpend >= minimumSpend && !customer.hasOutstandingBalance
    }
}

struct ActiveAccountSpec: Specification {
    func isSatisfiedBy(_ customer: Customer) -> Bool {
        customer.status == .active
    }
}

// Compose with AND combinator
let eligible = PremiumEligibleSpec(minimumSpend: Money(500, .usd))
    .and(ActiveAccountSpec())
let qualifyingCustomers = allCustomers.filter { eligible.isSatisfiedBy($0) }

