// Entity: equality by identity, not by attribute values
struct Customer: Equatable, Hashable {
    let customerId: CustomerID  // The stable identity
    var name: PersonName
    var email: EmailAddress
    var shippingAddress: Address

    // Identity equality: same ID == same customer,
    // even if all other attributes differ
    static func == (lhs: Customer, rhs: Customer) -> Bool {
        lhs.customerId == rhs.customerId
    }

    func hash(into hasher: inout Hasher) {
        hasher.combine(customerId)
    }
}

let cached = Customer(customerId: id, name: "Alice", ...)
let fresh  = Customer(customerId: id, name: "Alice Smith", ...)
assert(cached == fresh)  // true — same identity, different name

// Value object: equality by all attribute values, no separate ID
struct Money: Equatable, Hashable {
    let amount: Decimal
    let currency: Currency

    // Value equality: every attribute must match
    static func == (lhs: Money, rhs: Money) -> Bool {
        lhs.amount == rhs.amount && lhs.currency == rhs.currency
    }

    func hash(into hasher: inout Hasher) {
        hasher.combine(amount)
        hasher.combine(currency)  // omitting currency would be a bug
    }
}

let a = Money(amount: 50, currency: .usd)
let b = Money(amount: 50, currency: .usd)
let c = Money(amount: 50, currency: .eur)
assert(a == b)   // true — identical attributes
assert(a != c)   // true — different currency

// Side-effect-free behavior on a value object
struct DateRange: Equatable {
    let start: Date
    let end: Date

    var duration: TimeInterval { end.timeIntervalSince(start) }

    // Returns new value — does not mutate self
    func extending(by days: Int) -> DateRange {
        DateRange(start: start, end: Calendar.current.date(byAdding: .day, value: days, to: end)!)
    }

    func overlapping(with other: DateRange) -> DateRange? {
        let overlapStart = max(start, other.start)
        let overlapEnd   = min(end,   other.end)
        guard overlapStart < overlapEnd else { return nil }
        return DateRange(start: overlapStart, end: overlapEnd)
    }
}

