// Typed ID wrapping UUID — entity has identity at construction
struct OrderID: Hashable, Codable {
    let rawValue: UUID
    init() { rawValue = UUID() }           // generated in app, not DB
    init(_ existing: UUID) { rawValue = existing }
}

struct Order {
    let orderId: OrderID                   // identity assigned at creation
    let customerId: CustomerID
    private(set) var lines: [OrderLine]

    init(for customer: CustomerID) {
        self.orderId = OrderID()           // no database round-trip needed
        self.customerId = customer
        self.lines = []
    }
}

// Before: oversized aggregate — comments included because "they belong to a post"
struct BlogPost {
    let postId: PostID
    var title: String
    var body: String
    var comments: [Comment]   // thousands of rows loaded per request
    var votes: [Vote]          // no invariant spans Post and Comment
    var subscribers: [UserID]  // no invariant spans Post and Subscriber
}

// After: sized by invariant — only what the Post root actually governs
struct BlogPost {
    let postId: PostID
    var title: String
    var body: String
    var status: PostStatus
    // Cross-aggregate references by ID only
    // Comments, votes, subscribers are separate aggregates
}

// Comments are their own consistency unit
struct Comment {
    let commentId: CommentID
    let postId: PostID         // reference by ID — not an object
    let authorId: UserID
    var content: CommentContent
}
